"""Complete full fish and meat dishes with vinaigrettes."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Main dishes',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up as directed to keep the food covered.')
def eggs(a,k='eggs'):return I(k,a,'','large eggs','Use the same number of large pasteurized shell eggs; cook fully as directed.')
LEFT='Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder. Use within 3 days. Reheat cooked leftovers to 74°C (165°F).'
TEMP=' Modern cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Veal variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'

r=add(144,'Merluza with Warm Egg and Tarragon Vinaigrette',6,50,'Gently poached hake is topped with warm olive oil and a chunky tarragon-vinegar sauce containing hard-boiled eggs, onion, garlic and parsley.',[I('fish',1200,'g','boneless hake fillet, skin on, in one or two large pieces','Use the same weight of thick cod or pollock fillet; cook to the same endpoint.'),water(2000,'fishwater'),eggs(6),water(1500,'eggwater'),I('onion',60,'g','peeled onion, finely chopped','Use the same weight of shallot.'),I('garlic',5,'g','peeled garlic, finely minced','Use the same weight of shallot for a different flavor.'),I('parsley',10,'g','fresh parsley, finely chopped','Use the same weight of chives for a different herb flavor.'),vinegar(45,'tarragon'),salt(.5),I('whitepepper',.25,'tsp','ground white pepper','Use the same amount of black pepper.'),I('clove',.0625,'tsp','ground cloves','Omit for milder seasoning.'),I('nutmeg',.125,'tsp','ground nutmeg','Use the same amount of ground mace.'),oil(90)],['Put {{eggs}} in a pan with {{eggwater}}, topping up if needed to cover by about 2 cm. Bring to a boil, cover, remove from the heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout. Separate the yolks and finely chop the whites.','Mix {{onion}}, {{garlic}}, {{parsley}}, {{vinegar}}, {{salt}}, {{whitepepper}}, {{clove}} and {{nutmeg}} in a bowl. Stir and press with a spoon for about 15 minutes, then mash in the cooked yolks and fold in the chopped whites.','Check {{fish}} for pin bones and remove them. Lay the large pieces in a wide shallow pan with cold {{fishwater}}, adding a little more if needed to cover. Heat gradually to a bare simmer, then keep at a gentle simmer for about 8–15 minutes, until the thickest part reaches 63°C (145°F) and the flesh is opaque and flakes easily. Do not assume it is cooked at the first boil.','Lift the fish carefully onto a warm deep serving platter and drain away excess water. Warm {{oil}} in a small pan over low heat for 1–2 minutes, just until warm and fluid; do not let it smoke. Spoon it over the fish, then spread the egg-and-vinegar mixture over the top. Serve immediately.',LEFT],'The original says the whole piece of hake, not necessarily a whole fish. Two large boneless pieces are an explicit modern handling choice. Six hard-boiled yolks and their whites are retained. Missing fish, oil, vinegar, vegetable and spice amounts are supplied. The unspecified mixed spices become a disclosed white-pepper, clove and nutmeg blend. Warm oil replaces the source smoking-hot oil to avoid splashing over wet fish. The unreliable first-boil cooking endpoint is replaced with a measured fish temperature.');r['source']+=TEMP

r=add(147,'Polish-American Fish and Beet Vinaigrette Salad',6,120,'Cooked fish, potatoes, beets and pickled vegetables form a substantial cold salad with an egg-yolk mustard dressing and a colorful garnish.',[I('fish',600,'g','boneless skinless cod fillets','Use the complete fresh-herring variation for a different traditional fish choice.'),water(1000,'fishwater'),I('potatoes',500,'g','small waxy potatoes, scrubbed','Use the same weight of another firm salad potato.'),water(1500,'potatowater'),I('beets',300,'g','small whole beets, scrubbed','Use the same weight of golden beets; color and flavor differ.'),water(1500,'beetwater'),eggs(2),eggs(4,'sauceeggs'),water(1500,'eggwater'),I('gherkins',40,'g','drained pickled gherkins','Use the same weight of cornichons.'),I('cucumber',80,'g','drained fermented cucumber pickles','Use the same weight of sour dill pickles.'),I('mushrooms',80,'g','commercially prepared marinated mushrooms, drained','Use the same weight of drained pickled artichoke hearts for a different salad.'),oil(30),vinegar(15),I('sauceoil',60,'ml','olive oil for the yolk dressing','Use the same volume of mild sunflower oil.'),I('saucevinegar',30,'ml','white wine vinegar for the yolk dressing','Use the same volume of cider vinegar.'),I('sugar',1,'tsp','granulated sugar','Use the same amount of caster sugar.'),I('mustard',1,'tsp','prepared Dijon mustard','Use the same amount of prepared yellow mustard.'),I('capers',15,'g','drained capers','Use the same weight of finely chopped sour cucumber pickle.'),I('cabbage',60,'g','red cabbage, finely shredded','Use the same weight of shredded green cabbage.')],['Put {{potatoes}} in a pan with {{potatowater}}. Bring to a boil and simmer for 15–25 minutes until just tender. Drain, cool until safe to handle, peel if desired and slice thinly. Spread in a shallow dish to cool.','In a separate pan, cover {{beets}} with {{beetwater}}. Simmer for 30–50 minutes until a small knife enters easily, adding water if needed to keep them covered. Drain and cool briefly, then rub off the skins and slice thinly. Keep separate from the potatoes while cooling.','Put {{eggs}} and {{sauceeggs}} together in a pan with {{eggwater}}, topping up to cover by 2 cm if needed. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water and peel. Check that every yolk is firm. Reserve one third of the cooked eggs whole for the salad. Separate the yolks of the remaining two thirds for the sauce and refrigerate their whites for another dish.','Check {{fish}} for bones and remove them. Bring {{fishwater}} to a bare simmer in a wide pan. Add the fish and poach gently for 6–10 minutes, until the thickest part reaches 63°C (145°F) and flakes easily. Lift out, drain and flake into bite-size pieces.','Spread the cooked fish and vegetables in separate shallow dishes, cover and refrigerate promptly, within 2 hours of cooking. Chill for about 45 minutes at 4°C (40°F) or colder. Slice the reserved whole salad eggs, {{gherkins}} and {{cucumber}}; cut {{mushrooms}} into small pieces.','Set aside half the sliced beets, half the sliced eggs and half the sliced cucumber for garnish. Gently mix the remaining portions with the potatoes, fish, gherkins, mushrooms, {{oil}} and {{vinegar}}. Arrange on a serving platter.','Mash the reserved cooked sauce yolks very finely with {{saucevinegar}}, {{sugar}} and {{mustard}}. Gradually whisk in {{sauceoil}} until smooth. Spoon over the salad.','Garnish with the reserved beet, egg and cucumber slices, {{capers}} and {{cabbage}}. Serve cold. Refrigerate leftovers promptly and use within 2 days.'],'The complete original Polish paragraph includes cooked fish or herring and a separate four-yolk sauce. The sauce yolks are not described as raw or cooked; this adaptation explicitly cooks them fully, producing a thick cooked-yolk dressing. Two additional eggs supply the salad and garnish. Both source oil-and-vinegar additions are retained and measured separately. Vegetable, fish, pickle and garnish quantities are supplied. The source garnish is divided from the listed ingredients, not double-counted. Total time includes parallel cooking and chilling.');r['source']+=TEMP
variant(r,'fresh-herring','Fish and beet salad with cooked herring',[dict(i,name='fresh boneless herring fillets, skin removed',substitution='Use the cod base recipe if preferred; this variation uses fresh fish, not raw salted herring.') if i['key']=='fish' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))

r=add(152,'Calf’s Head with Tomato Sauce and Vinaigrette',6,240,'Tender simmered calf’s-head meat is coated with a light tomato sauce and served with parsley, caper and onion vinaigrette.',[I('head',1200,'g','boneless calf’s-head meat and skin, cleaned and prepared by an inspected butcher, tongue and brains removed','Use the same weight of beef cheek for a different texture and flavor; simmer until tender.'),water(2000,'blanchwater'),water(2500),I('lemon',.5,'','lemon, washed','Use half a lime for a different flavor.'),I('potvinegar',30,'ml','white wine vinegar for the simmering liquid','Use the same volume of cider vinegar.'),I('peppercorns',10,'','whole black peppercorns','Use the same number of white peppercorns.'),I('bay',1,'','dried bay leaf','Omit if unavailable.'),I('onion',120,'g','peeled onion, quartered','Use the same weight of trimmed leek, rinsed well.'),I('carrot',100,'g','peeled carrot, cut into large pieces','Use the same weight of peeled parsnip.'),I('potparsley',5,'g','fresh parsley sprigs','Use the same weight of parsley stems.'),I('tomato',300,'ml','plain unsalted tomato juice','Use 150 ml plain tomato passata mixed with 150 ml water.'),I('starch',8,'g','cornstarch (cornflour)','Use the same weight of arrowroot starch, heating just until thickened.'),water(15,'slurrywater'),oil(45),vinegar(15),I('gratedonion',1,'tsp','finely grated onion for the vinaigrette','Use the same amount of grated shallot.'),parsley(1),I('capers',1,'tsp','drained capers, chopped','Use the same amount of chopped sour cucumber pickle.'),salt(.25),pepper(.125)],['Check {{head}} carefully for any remaining bone fragments and remove them. Put in a deep pot with {{blanchwater}}, adding more cold water only if needed to cover. Bring to a boil and simmer for 5 minutes. Drain, discard the blanching water and rinse the pot.','When the meat is cool enough to handle with tongs, rub its surface with the cut side of {{lemon}}, then discard the lemon. Return the meat to the clean pot with hot {{water}}, {{potvinegar}}, {{peppercorns}}, {{bay}}, {{onion}}, {{carrot}} and {{potparsley}}. Add more hot water only if needed to cover.','Cover and simmer very gently for 2½–3½ hours until the meat and skin are tender but still hold their shape. Maintain enough liquid to cover them, topping up as needed. The thickest meat must reach at least 71°C (160°F), and tenderness determines the longer cooking time.','Lift the meat out, discard the cooking vegetables and spices, and cut the meat into neat serving pieces, checking again for any small bone fragments. Keep covered and warm while making the sauces.','Bring {{tomato}} to a gentle simmer in a small saucepan. Mix {{starch}} with cold {{slurrywater}} until smooth, whisk into the tomato juice and simmer for 2 minutes, stirring, until lightly thickened. Spoon this tomato sauce over the meat.','Whisk {{vinegar}}, {{salt}} and {{pepper}} in a bowl. Gradually whisk in {{oil}}, then stir in {{gratedonion}}, {{parsley}} and {{capers}}. Serve the vinaigrette in a separate small bowl with the hot tomato-coated meat.',LEFT],'The full original boiling cross-reference is expanded, but a butcher prepares and debones the head; the tongue and brains are not part of this dish. The preliminary cold soak is omitted because the meat is already professionally cleaned. The original tomato-and-cornstarch sauce is supplied in full. Egg, breadcrumbs and butter in the extracted list belong to the preceding baked-head recipe and are not used in this separate vinaigrette dish. Missing meat, tomato, starch and herb quantities are explicit modern estimates.');r['source']+=TEMP

r=add(155,'Sour-Braised Calf’s Brain with Tarragon and Chervil',2,100,'Gently poached calf’s brain is briefly reheated in a light tarragon-vinegar broth with blanched fresh herbs.',[I('brains',300,'g','food-grade calf’s brain, cleaned and membrane removed by an inspected meat supplier','Use the same weight of food-grade lamb brain from an inspected supplier for a different flavor.'),water(500,'poachwater'),I('poachvinegar',500,'ml','white wine vinegar for poaching','Use the same volume of cider vinegar.'),vinegar(62.5,'tarragon'),I('stock',200,'ml','unsalted prepared veal stock','Use the same volume of unsalted prepared chicken or vegetable stock.'),salt(.25),pepper(.125),I('bay',1,'','dried bay leaf','Omit if unavailable.'),I('tarragon',3,'g','fresh tarragon leaves','Use the same weight of fresh parsley for a different herb flavor.'),I('chervil',3,'g','fresh chervil leaves','Use the same weight of fresh parsley for a different herb flavor.'),I('parsley',3,'g','fresh parsley leaves','Use the same weight of fresh chervil.'),water(500,'herbwater'),I('herbsalt',2,'g','fine salt for the herb water','Reduce or omit.')],['Bring {{poachwater}} and {{poachvinegar}} to a gentle simmer in a snug saucepan. Add {{brains}}, topping up with equal amounts of water and vinegar only if needed to cover. Poach gently for about 10–15 minutes, until firm and at least 71°C (160°F) in the center.','Transfer the brain and enough poaching liquid to cover it into a shallow heatproof container. Set the container in a cold-water bath without allowing water into the food; change the bath water as it warms. Cover and refrigerate promptly, within 2 hours of cooking, until cool, about 30–45 minutes. Lift out, drain and discard all the poaching liquid.','In a small saucepan, combine {{vinegar}}, {{stock}}, {{salt}}, {{pepper}} and {{bay}}. Simmer gently for 5–8 minutes, then remove the bay leaf.','Bring {{herbwater}} and {{herbsalt}} to a boil. Add {{tarragon}}, {{chervil}} and {{parsley}} for 15–20 seconds. Drain through a fine sieve, cool briefly under cold running water, press out excess water and chop finely.','Cut the cooled brain into large pieces and arrange in a small saucepan with the chopped herbs. Pour over the hot vinegar-stock sauce. Bring gently to a simmer and heat for 3–5 minutes, until the brain reaches 74°C (165°F) throughout. Avoid vigorous stirring so the pieces remain intact. Serve immediately.',LEFT],'The original printed page118 clearly specifies one sixteenth liter of tarragon vinegar, or 62.5 ml, not the extracted half liter. The separate equal-parts water-and-vinegar poach is retained. Brain weight, stock volume, herb quantities, cooling method and cooking endpoints are supplied modern choices. Cooling takes place promptly in a shallow container and refrigerator instead of an unspecified room-temperature wait. This is a freshly cooked sour-braised dish, not a shelf-stable pickle.');r['source']+=' Original scan checked: Wiener Kochbuch, recipe547, printed page118. '+TEMP

assert len(newids)==4,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full fish, vegetable, meat and sauce methods completed from original sources; source quantities and modern choices distinguished','repair-batch-020.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))
